//ait.ethz.ch/people\", \"now\": \"FH Ost \u6559\u6388\", \"background\": null, \"chinese_or_csc\": null, \"note\": \"\u8bfe\u9898\u65b9\u5411\u636e\u5176\u516c\u5f00\u8bba\u6587\u6982\u62ec\uff0cAIT \u9875\u9762\u4ec5\u5217\u5e74\u4efd\u4e0e\u53bb\u5411\"}, {\"name\": \"Velko Vechev\", \"status\": \"alumni\", \"start_year\": 2018, \"graduation_year\": 2024, \"research_topic\": \"Computational design of input/haptic devices\", \"topic_zh\": \"\u8f93\u5165/\u89e6\u89c9\u8bbe\u5907\u7684\u8ba1\u7b97\u8bbe\u8ba1\", \"url\": \"https://ait.ethz.ch/people\", \"now\": \"LatticeFlow AI\", \"background\": null, \"chinese_or_csc\": null, \"note\": \"\u8bfe\u9898\u65b9\u5411\u636e\u5176\u516c\u5f00\u8bba\u6587\u6982\u62ec\uff0cAIT \u9875\u9762\u4ec5\u5217\u5e74\u4efd\u4e0e\u53bb\u5411\", \"now_zh\": \"LatticeFlow AI\"}, {\"name\": \"Thomas Langerak\", \"status\": \"alumni\", \"start_year\": 2018, \"graduation_year\": 2024, \"research_topic\": \"Haptic/mid-air interaction & UI adaptation\", \"topic_zh\": \"\u89e6\u89c9/\u7a7a\u4e2d\u4ea4\u4e92\u4e0e\u754c\u9762\u81ea\u9002\u5e94\", \"url\": \"https://ait.ethz.ch/people\", \"now\": \"Aalto CBL \u535a\u58eb\u540e\", \"background\": null, \"chinese_or_csc\": null, \"note\": \"\u8bfe\u9898\u65b9\u5411\u636e\u5176\u516c\u5f00\u8bba\u6587\u6982\u62ec\uff0cAIT \u9875\u9762\u4ec5\u5217\u5e74\u4efd\u4e0e\u53bb\u5411\"}, {\"name\": \"Xu Chen / Chen Guo / Yufeng Zheng / Zijian Dong / Gengyan Li / Muhammed Kocabas / Hsuan-I Ho / Egor Zakharov / Sammy Christen / Emre Aksan / Seonwook Park\", \"status\": \"alumni\", \"graduation_year\": \"2020\u20132025\", \"research_topic\": \"Neural avatars, human body/face/hand modeling, motion synthesis, gaze\", \"topic_zh\": \"\u795e\u7ecf\u5316\u8eab\u3001\u4eba\u4f53/\u9762\u90e8/\u624b\u90e8\u5efa\u6a21\u3001\u52a8\u4f5c\u751f\u6210\u3001\u89c6\u7ebf\u4f30\u8ba1\uff08\u90e8\u5206\u4e3a\u535a\u58eb\u540e\uff0c\u9875\u9762\u672a\u533a\u5206\uff09\", \"url\": \"https://ait.ethz.ch/people\", \"now\": \"Google/Meta/NVIDIA/ByteDance PicoXR/Disney \u7b49\uff08\u9875\u9762\u6240\u5217\uff09\", \"background\": null, \"chinese_or_csc\": null, \"now_zh\": \"Google/Meta/NVIDIA/ByteDance PicoXR/Disney \u7b49\uff08\u9875\u9762\u6240\u5217\uff09\"}], \"total_estimate\": \"\u5728\u8bfb 7\u20138 / 2014\u20132025 \u5df2\u79bb\u7ec4\u6210\u5458\u7ea6 30\uff08\u542b\u535a\u58eb\u540e\uff1b\u7edd\u5927\u591a\u6570\u4e3a\u535a\u58eb\uff09\", \"student_pattern_zh\": \"\u8ba1\u7b97\u673a\u89c6\u89c9+\u56fe\u5f62+HCI\uff1a\u4eba\u4f53/\u624b\u90e8/\u9762\u90e8 3D \u91cd\u5efa\u4e0e\u795e\u7ecf\u5316\u8eab\u3001\u624b-\u7269\u4ea4\u4e92\u3001\u52a8\u4f5c\u751f\u6210\u3001\u7a7a\u4e2d\u624b\u52bf\u8bc6\u522b\u3001\u8ba1\u7b97\u4ea4\u4e92\u4e0e\u81ea\u9002\u5e94 MR \u754c\u9762\u3002\u9ad8\u5ea6\u7b97\u6cd5/\u6df1\u5ea6\u5b66\u4e60\u9a71\u52a8\uff0c\u9876\u4f1a\uff08CVPR/SIGGRAPH/CHI\uff09\u5bfc\u5411\u3002\", \"design_background_ok_zh\": \"\u51e0\u4e4e\u65e0\uff1a\u6210\u5458\u5747\u4e3a CS/EE \u80cc\u666f\uff0c\u5f3a\u8c03\u6df1\u5ea6\u5b66\u4e60\u4e0e\u56fe\u5f62\u5b66\u3002\", \"chinese_students_zh\": \"\u591a\u540d\u62fc\u97f3\u59d3\u540d\u6bd5\u4e1a\u751f\uff08Jie Song\u3001Xu Chen\u3001Zijian Dong\u3001Gengyan Li\u3001Chengwei Zheng\u3001Zicong Fan\u3001Chen Guo\u3001Yufeng Zheng \u7b49\uff09\u53ca\u5728\u8bfb Lixin Xue\uff0c\u663e\u793a\u534e\u4eba\u6bd4\u4f8b\u5f88\u9ad8\uff1b\u6765\u6e90\u672a\u660e\u793a\u56fd\u7c4d/CSC\uff08ETH \u535a\u58eb\u4e3a\u5168\u85aa\uff0c\u4e00\u822c\u975e CSC\uff09\u3002\", \"implication_zh\": \"\u624b\u52bf/\u624b\u90e8\u4ea4\u4e92\u662f\u5176\u6838\u5fc3\uff08Jie Song \u7a7a\u4e2d\u624b\u52bf\u3001Spurr/Fan \u624b\u90e8\u91cd\u5efa\uff09\uff0c\u4e0e\u7528\u6237\u2018\u624b\u52bf\u9a71\u52a8\u5177\u8eab\u4ea4\u4e92\u2019\u9ad8\u5ea6\u76f8\u5173\uff0c\u4f46\u7ec4\u5185\u8981\u6c42\u9876\u5c16 CV/ML \u80fd\u529b\uff0cMFA \u80cc\u666f\u51e0\u4e4e\u65e0\u6cd5\u76f4\u63a5\u8fdb\u5165\u3002\u66f4\u73b0\u5b9e\u7684\u662f\u5f15\u7528\u5176\u624b\u52bf\u8bc6\u522b\u6210\u679c\u4f5c\u4e3a\u7528\u6237\u7814\u7a76\u7684\u6280\u672f\u57fa\u7840\uff0c\u800c\u975e\u7533\u8bf7\u8be5\u7ec4\u3002\u98ce\u9669\u6781\u9ad8\u3002\", \"sources\": [\"https://ait.ethz.ch/people\"], \"searched\": [\"AIT Lab People \u9875\uff08\u542b Previous Members \u53bb\u5411\uff09\", \"ETH Research Collection\uff08\u672a\u9010\u7bc7\u6838\u5bf9\u9898\u76ee\uff09\"]}, \"title_zh\": \"\u8ba1\u7b97\u673a\u79d1\u5b66\u6b63\u6559\u6388\uff1b\u5148\u8fdb\u4ea4\u4e92\u6280\u672f\uff08AIT\uff09\u5b9e\u9a8c\u5ba4\u8d1f\u8d23\u4eba\uff1b\u667a\u80fd\u4ea4\u4e92\u7cfb\u7edf\u7814\u7a76\u6240\u6240\u957f\", \"unit_zh\": \"\u8ba1\u7b97\u673a\u79d1\u5b66\u7cfb\uff08D-INFK\uff09\uff0c\u82cf\u9ece\u4e16\u8054\u90a6\u7406\u5de5\u5b66\u9662\", \"email_hook_zh\": \"\u60a8\u5728\u624b\u2014\u7269\u4ea4\u4e92\u65b9\u9762\u7684\u7814\u7a76\uff08HOLD\u3001\u7b2c\u4e00\u4eba\u79f0\u624b\u90e8\u4ea4\u4e92\u57fa\u51c6\uff09\u662f\u6211\u57fa\u4e8e\u6d4f\u89c8\u5668\u7684\u624b\u52bf\u539f\u578b\u76ee\u524d\u7528 MediaPipe \u8fd1\u4f3c\u5b9e\u73b0\u7684\u6280\u672f\u57fa\u7840\u3002\", \"csc_status_zh\": \"\u5df2\u6682\u505c\u6216\u505c\u6b62\"}, {\"name\": \"Judith D\u00f6rrenb\u00e4cher\", \"school_en\": \"University of Siegen \u2013 Faculty III, ENACT Junior Research Group (Dr. Judith D\u00f6rrenb\u00e4cher), with Prof. Marc Hassenzahl's HCI/Experience Design group\", \"school_zh\": \"\u9521\u6839\u5927\u5b66\", \"country\": \"\", \"title\": \"Postdoctoral researcher; Head of the VolkswagenStiftung-funded ENACT Junior Research Group (2026\u20132031)\", \"unit\": \"Faculty III (School of Economic Disciplines), Experience & Interaction Design / ENACT, University of Siegen\", \"homepage\": \"https://jobs.uni-siegen.de/job/Researcher-%28mfd%29-Interaction-Design-&-Physical-Prototyping-57072/1442365433/\", \"email\": \"judith.doerrenbaecher@uni-siegen.de\", \"relevance\": 7, \"claim\": \"D\u00f6rrenb\u00e4cher \u662f\u672c\u5c97\u4f4d\uff08ENACT, Interaction Design & Physical Prototyping\uff09\u7684\u7ec4\u957f\u548c\u8054\u7cfb\u4eba\uff0c\u505a Research through Design\u3001\u8868\u6f14\u6027/\u601d\u8fa8\u8bbe\u8ba1\u4e0e\u673a\u5668\u4eba\u793e\u4f1a\u4e92\u52a8\uff0c\u4e0e\u7528\u6237'\u539f\u578b\u5373\u8bc1\u636e'\u7684\u65b9\u6cd5\u8bba\u5b8c\u5168\u540c\u8def\u3002\", \"evidence_homepage\": \"https://jobs.uni-siegen.de/job/Researcher-%28mfd%29-Interaction-Design-&-Physical-Prototyping-57072/1442365433/\", \"evidence_papers\": [{\"title\": \"The Minority Report Fallacy: Celebrating Gestures While Forgetting Futures\", \"year\": 2026, \"venue\": \"ACM interactions\", \"url\": \"https://doi.org/10.1145/3799785\", \"link_to_user\": \"\u5bf9'\u624b\u52bf\u4ea4\u4e92\u5d07\u62dc'\u7684\u6279\u5224 \u2192 \u7528\u6237\u5fc5\u987b\u56de\u5e94\u7684\u5173\u952e\u6587\u732e\uff0c\u53ef\u4f5c\u4e3a\u63d0\u6848\u7684\u95ee\u9898\u610f\u8bc6\", \"title_zh\": \"\u300a\u5c11\u6570\u6d3e\u62a5\u544a\u300b\u8c2c\u8bef\uff1a\u9882\u626c\u624b\u52bf\u5374\u9057\u5fd8\u672a\u6765\"}, {\"title\": \"Mediating Urban Social Encounters \u2013 Co-Design of Robotic Street Furniture with Adolescents\", \"year\": 2026, \"venue\": \"CHI 2026\", \"url\": \"https://doi.org/10.1145/3772318.3791189\", \"link_to_user\": \"\u516c\u5171\u7a7a\u95f4\u4e2d\u7684\u4ea4\u4e92\u539f\u578b\u4e0e\u5171\u521b \u2192 \u535a\u7269\u9986\u516c\u5171\u7a7a\u95f4\u7684\u53c2\u4e0e\u5f0f\u8bbe\u8ba1\", \"title_zh\": \"\u4e2d\u4ecb\u57ce\u5e02\u793e\u4f1a\u76f8\u9047\u2014\u2014\u4e0e\u9752\u5c11\u5e74\u5171\u540c\u8bbe\u8ba1\u673a\u5668\u4eba\u8857\u9053\u8bbe\u65bd\"}, {\"title\": \"The Quality of Speculation \u2013 A Scoping Review\", \"year\": 2025, \"venue\": \"ACM DIS 2025\", \"url\": \"https://doi.org/10.1145/3715336.3735794\", \"link_to_user\": \"\u601d\u8fa8\u8bbe\u8ba1\u8d28\u91cf \u2192 \u7528\u6237\u628a\u5b97\u6559/\u4fee\u590d\u4eea\u5f0f\u8f6c\u8bd1\u4e3a\u4ea4\u4e92\u7684\u8bbe\u8ba1\u8bba\u8bc1\", \"title_zh\": \"\u63a8\u6d4b\u7684\u8d28\u91cf\u2014\u2014\u8303\u56f4\u7efc\u8ff0\"}], \"evidence_projects_funding\": \"\u5927\u4f17\u57fa\u91d1\u4f1a Change! Fellowship \u9879\u76ee ENACT\uff08\u7f16\u53f7 0200624\uff0c\u20ac1,958,754\uff0c2026-10-01 \u81f3 2031-09-30\uff09\uff1b\u4e0e FFT D\u00fcsseldorf \u827a\u672f\u5bb6\u9a7b\u7559\u5408\u4f5c\uff1b\u5c97\u4f4d TV-L 13\uff0c\u622a\u6b62 2026-11-15\u3002\", \"fit_to_user\": \"\u5c97\u4f4d\u660e\u786e\u6b22\u8fce Design/Interaction Design \u7855\u58eb\u4e0e\u7269\u7406\u8ba1\u7b97\u539f\u578b\u80fd\u529b\uff1b\u7528\u6237\u7684 Arduino \u4ee5\u5916\u7684 MediaPipe/Three.js/HoloLens \u539f\u578b\u4e0e\u7167\u660e\u786c\u4ef6\u7ecf\u9a8c\u53ef\u76f4\u63a5\u5bf9\u63a5\uff1b'\u4eea\u5f0f\u5316\u624b\u52bf'\u53ef\u8f6c\u5316\u4e3a\u516c\u5171\u7a7a\u95f4\u793e\u4f1a\u4ea4\u5f80\u9898\u76ee\u3002\", \"counterargument_risk\": \"ENACT \u4e3b\u9898\u662f\u57ce\u5e02\u516c\u5171\u7a7a\u95f4\u7684\u793e\u4f1a\u76f8\u9047\u4e0e\u667a\u80fd\u6280\u672f\uff0c\u4e0d\u662f\u535a\u7269\u9986\uff1bD\u00f6rrenb\u00e4cher \u5c1a\u672a\u53d6\u5f97\u6559\u6388\u804c\u79f0\uff0c\u6b63\u5f0f\u535a\u58eb\u5bfc\u5e08\u53ef\u80fd\u7531 Hassenzahl \u62c5\u4efb\uff08\u9700\u786e\u8ba4\uff09\uff1b\u5fb7\u8bed\u4e3a\u52a0\u5206\u9879\uff1b\u5c97\u4f4d\u622a\u6b62\u65e9\u4e8e\u7528\u6237\u96c5\u601d\u8ba1\u5212\u3002\", \"email_hook\": \"Your interactions piece \\\"The Minority Report Fallacy\\\" made me rethink my own gesture prototypes, and ENACT's performative, research-through-design approach is the method I want to train in.\", \"sources\": [\"https://jobs.uni-siegen.de/job/Researcher-%28mfd%29-Interaction-Design-&-Physical-Prototyping-57072/1442365433/\", \"https://www.judithdoerrenbaecher.de/judith-doerrenbaecher\", \"https://www.judithdoerrenbaecher.de/publications\", \"https://projektdatenbank.volkswagenstiftung.de/projekt/0200624\", \"https://orcid.org/0000-0002-3968-461X\"], \"verified\": true, \"csc_note\": \"\u5c97\u4f4d\u5236\uff1aENACT\uff08\u5927\u4f17\u57fa\u91d1\u4f1a Change! Fellowship, 2026-10\u20132031-09\uff09TV-L 13 100% \u804c\u4f4d\uff0c3 \u5e74\u53ef\u5ef6 18 \u4e2a\u6708\uff0c\u622a\u6b62 2026-11-15\uff0c\u5165\u804c 2027-04-01\u3002\", \"matched_keywords\": [\"research through design\", \"interaction design\", \"physical prototyping\", \"gesture interaction\", \"public space\"], \"csc_status\": \"unknown\", \"in_user_csc_list\": false, \"email_draft\": {\"to\": \"judith.doerrenbaecher@uni-siegen.de\", \"subject\": \"Application enquiry: ENACT PhD position (Interaction Design & Physical Prototyping)\", \"body\": \"Dear Dr. D\u00f6rrenb\u00e4cher,\\n\\nYour interactions article \\\"The Minority Report Fallacy: Celebrating Gestures While Forgetting Futures\\\" made me look hard at my own gesture prototypes, and the robotic street furniture you co-designed with adolescents (CHI 2026) is the kind of performative, research-through-design work I want to do. I would like to apply for a PhD through the ENACT position \\\"Researcher (m/f/d) \u2013 Interaction Design & Physical Prototyping\\\" (deadline 15 November 2026).\\n\\nSince November 2025 I have directed the Digital ICH Design and Production teaching and research office at Quanzhou Huaguang College, teaching 3D character design and leading a VR collaborative lighting design project (JAT251371). Before that I was a lighting product manager at OSRAM/LEDVANCE (nine series, ~100 SKUs, ~US$8M sales; light-distribution analysis for Zayed International Airport) and led user research at LEEDARSON for smart-lighting lines selling over US$30M. Lighting work lets me build physical, responsive light; the office brings students for co-design.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures rebuilt as GPU particle clouds in Three.js, with MediaPipe hand tracking in the browser, so visitors brush away the \\\"dust\\\" with a fingertip and hold their palms together to reveal the gilded figure. A companion project does the same for Chinese bronzes.\\n\\nWithin ENACT I would explore how embodied, ritual-like gestures and responsive light can mediate encounters between strangers in public space \u2014 moving my work from single-visitor screens to shared, physical installations prototyped with artists at FFT D\u00fcsseldorf, and studied in the field.\\n\\nTo be direct: my degrees are in design, not computer science, and I have no first-author paper yet (I co-authored two MR papers). I bring working prototypes, a granted invention patent on an MR customisation method, and a practice-based approach I would turn into peer-reviewed studies early.\\n\\nI will apply through the university portal as required; I am writing first to ask whether my design background and prototypes match what you are looking for. Would you be open to supervising this topic? I would be glad to send a two-page proposal.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1aMinority Report Fallacy\uff08\u6279\u5224\u624b\u52bf\u5d07\u62dc\uff09\u2014\u2014\u7528\u6237\u9700\u5728\u4fe1\u4e2d\u8868\u660e\u81ea\u5df1\u610f\u8bc6\u5230\u624b\u52bf\u4ea4\u4e92\u7684\u5c40\u9650\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1a\u5c97\u4f4d\u53ea\u63a5\u53d7\u95e8\u6237\u7533\u8bf7\uff08\u622a\u6b62 2026-11-15\uff0c\u5165\u804c 2027-04-01\uff09\uff1b\u6b63\u5f0f\u535a\u58eb\u5bfc\u5e08\u662f\u5426\u4e3a Hassenzahl\uff1b\u82f1\u8bed\u8bc1\u660e\u65f6\u95f4\uff08\u96c5\u601d 2027-03 \u592a\u665a\uff0c\u95ee\u80fd\u5426\u5148\u7528\u5176\u4ed6\u8bc1\u660e\uff09\uff1b\u5fb7\u8bed\u4e3a\u52a0\u5206\u9879\u3002\", \"subject_zh\": \"\u7533\u8bf7\u54a8\u8be2\uff1aENACT \u535a\u58eb\u5c97\u4f4d\uff08\u4ea4\u4e92\u8bbe\u8ba1\u4e0e\u5b9e\u4f53\u539f\u578b\uff09\", \"body_zh\": \"\u5c0a\u656c\u7684 D\u00f6rrenb\u00e4cher \u535a\u58eb\uff1a\\n\\n\u60a8\u5728 interactions \u4e0a\u53d1\u8868\u7684\u6587\u7ae0\u201cThe Minority Report Fallacy: Celebrating Gestures While Forgetting Futures\u201d\uff08\u300a\u3008\u5c11\u6570\u6d3e\u62a5\u544a\u3009\u8c2c\u8bef\uff1a\u9882\u626c\u624b\u52bf\u800c\u9057\u5fd8\u672a\u6765\u300b\uff09\u8ba9\u6211\u8ba4\u771f\u5ba1\u89c6\u4e86\u81ea\u5df1\u7684\u624b\u52bf\u539f\u578b\uff0c\u800c\u60a8\u4e0e\u9752\u5c11\u5e74\u5171\u540c\u8bbe\u8ba1\u7684\u673a\u5668\u4eba\u8857\u9053\u8bbe\u65bd\uff08CHI 2026\uff09\u6b63\u662f\u6211\u60f3\u505a\u7684\u90a3\u79cd\u8868\u6f14\u6027\u7684\u8bbe\u8ba1\u7814\u7a76\u6cd5\uff08RtD\uff09\u5de5\u4f5c\u3002\u6211\u5e0c\u671b\u901a\u8fc7 ENACT \u5c97\u4f4d\u201cResearcher (m/f/d) \u2013 Interaction Design & Physical Prototyping\u201d\uff08\u7814\u7a76\u5458\u2014\u2014\u4ea4\u4e92\u8bbe\u8ba1\u4e0e\u5b9e\u4f53\u539f\u578b\uff1b\u622a\u6b62\u65e5\u671f 2026 \u5e74 11 \u6708 15 \u65e5\uff09\u7533\u8bf7\u535a\u58eb\u3002\\n\\n\u81ea 2025 \u5e74 11 \u6708\u8d77\uff0c\u6211\u62c5\u4efb\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\uff0c\u4e3b\u8bb2 3D \u89d2\u8272\u8bbe\u8ba1\uff0c\u5e76\u4e3b\u6301 VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\uff0c\u6211\u5728 OSRAM/LEDVANCE \u62c5\u4efb\u7167\u660e\u4ea7\u54c1\u7ecf\u7406\uff08\u8d1f\u8d23 9 \u4e2a\u4ea7\u54c1\u7cfb\u5217\u3001\u7ea6 100 \u4e2a SKU\uff0c\u9500\u552e\u989d\u7ea6 800 \u4e07\u7f8e\u5143\uff1b\u53c2\u4e0e Zayed \u56fd\u9645\u673a\u573a\u9879\u76ee\u7684\u914d\u5149\u5206\u6790\uff09\uff0c\u5e76\u5728 LEEDARSON\uff08\u7acb\u8fbe\u4fe1\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff0c\u76f8\u5173\u4ea7\u54c1\u7d2f\u8ba1\u9500\u552e\u8d85\u8fc7 3000 \u4e07\u7f8e\u5143\u3002\u7167\u660e\u5de5\u4f5c\u8ba9\u6211\u80fd\u591f\u5236\u4f5c\u5b9e\u4f53\u7684\u54cd\u5e94\u5f0f\u706f\u5149\uff1b\u6559\u7814\u5ba4\u5219\u80fd\u5e26\u6765\u53c2\u4e0e\u5171\u521b\u8bbe\u8ba1\u7684\u5b66\u751f\u3002\\n\\n\u6211\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u62c2\u5c18\u663e\u50cf\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u5728 Three.js \u4e2d\u88ab\u91cd\u5efa\u4e3a GPU \u7c92\u5b50\u4e91\uff0c\u501f\u52a9\u6d4f\u89c8\u5668\u4e2d\u7684 MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff0c\u53c2\u89c2\u8005\u7528\u6307\u5c16\u62c2\u53bb\u201c\u5c18\u57c3\u201d\uff0c\u518d\u53cc\u624b\u5408\u5341\uff0c\u5373\u53ef\u663e\u73b0\u938f\u91d1\u4f5b\u8eab\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u4ee5\u540c\u6837\u65b9\u5f0f\u5448\u73b0\u4e2d\u56fd\u9752\u94dc\u5668\u3002\\n\\n\u5728 ENACT \u4e2d\uff0c\u6211\u5e0c\u671b\u63a2\u7d22\u5177\u8eab\u7684\u3001\u7c7b\u4eea\u5f0f\u7684\u624b\u52bf\u4e0e\u54cd\u5e94\u5f0f\u706f\u5149\u5982\u4f55\u8c03\u8282\u516c\u5171\u7a7a\u95f4\u4e2d\u964c\u751f\u4eba\u4e4b\u95f4\u7684\u76f8\u9047\u2014\u2014\u628a\u6211\u7684\u5de5\u4f5c\u4ece\u5355\u4eba\u5c4f\u5e55\u63a8\u8fdb\u5230\u5171\u4eab\u7684\u5b9e\u4f53\u88c5\u7f6e\uff0c\u4e0e\u675c\u585e\u5c14\u591a\u592b FFT \u5267\u9662\u7684\u827a\u672f\u5bb6\u4e00\u8d77\u5236\u4f5c\u539f\u578b\uff0c\u5e76\u5f00\u5c55\u5b9e\u5730\u7814\u7a76\u3002\\n\\n\u5766\u767d\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u5747\u4e3a\u8bbe\u8ba1\u4e13\u4e1a\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6211\u53c2\u4e0e\u5408\u8457\u4e86\u4e24\u7bc7 MR \u8bba\u6587\uff09\u3002\u6211\u80fd\u5e26\u6765\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879\u5df2\u6388\u6743\u7684 MR \u5b9a\u5236\u65b9\u6cd5\u53d1\u660e");